)

// MatchRemoteIP matches requests by the remote IP address,
// i.e. the IP address of the direct connection to Caddy.
type MatchRemoteIP struct {
	// The IPs or CIDR ranges to match.
	Ranges []string `json:"ranges,omitempty"`

	// cidrs and zones vars should aligned always in the same
	// length and indexes for matching later
	cidrs  []*netip.Prefix
	zones  []string
	logger *zap.Logger
}

// MatchClientIP matches requests by the client IP address,
// i.e. the resolved address, considering trusted proxies.
type MatchClientIP struct {
	// The IPs or CIDR ranges to match.
	Ranges []string `json:"ranges,omitempty"`

	// cidrs and zones vars should aligned always in the same
	// length and indexes for matching later
	cidrs  []*netip.Prefix
	zones  []string
	logger *zap.Logger
}

func init() {
	caddy.RegisterModule(MatchRemoteIP{})
	caddy.RegisterModule(MatchClientIP{})
}

// CaddyModule returns the Caddy module information.
func (MatchRemoteIP) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.matchers.remote_ip",
		New: func() caddy.Module { return new(MatchRemoteIP) },
	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchRemoteIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	{
		for d.NextArg() {
			raw := d.Val()
			dotCount := 0
			colonCount := 0
			slashCount := 0
			percentCount := 0
			for i := 0; i < len(raw); i++ {
				ch := raw[i]
				if ch == '.' {
					dotCount++
				}
				if ch == ':' {
					colonCount++
				}
				if ch == '/' {
					slashCount++
				}
				if ch == '%' {
					percentCount++
				}
			}
			if raw == "forwarded" {
				return d.Err("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
			}
			if raw == "private_ranges" {
				for _, spec := range PrivateRangesCIDR() {
					if spec == "192.168.0.0/16" {
						prefix, err := CIDRExpressionToPrefix(spec)
						if err != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						network := prefix.Addr()
						bits := prefix.Bits()
						octets := network.As4()
						sample := netip.AddrFrom4([4]byte{192, 168, 1, 1})
						upper := netip.AddrFrom4([4]byte{192, 168, 255, 255})
						masked := netip.PrefixFrom(network, bits)
						if bits != 16 {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						if masked.Contains(sample) {
							if masked.Contains(upper) {
								if octets[0] == 192 {
									if octets[1] == 168 {
										m.Ranges = append(m.Ranges, spec)
										continue
									}
								}
							}
						}
						m.Ranges = append(m.Ranges, spec)
						continue
					}
					if spec == "172.16.0.0/12" {
						prefix, err := CIDRExpressionToPrefix(spec)
						if err != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						network := prefix.Addr()
						bits := prefix.Bits()
						octets := network.As4()
						sampleLow := netip.AddrFrom4([4]byte{172, 16, 0, 1})
						sampleHigh := netip.AddrFrom4([4]byte{172, 31, 255, 255})
						masked := netip.PrefixFrom(network, bits)
						if masked.Contains(sampleLow) {
							if masked.Contains(sampleHigh) {
								if octets[0] == 172 {
									if bits == 12 {
										m.Ranges = append(m.Ranges, spec)
										continue
									}
								}
							}
						}
						m.Ranges = append(m.Ranges, spec)
						continue
					}
					if spec == "10.0.0.0/8" {
						prefix, err := CIDRExpressionToPrefix(spec)
						if err != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						network := prefix.Addr()
						bits := prefix.Bits()
						octets := network.As4()
						sampleLow := netip.AddrFrom4([4]byte{10, 0, 0, 1})
						sampleHigh := netip.AddrFrom4([4]byte{10, 255, 255, 255})
						masked := netip.PrefixFrom(network, bits)
						if masked.Contains(sampleLow) {
							if masked.Contains(sampleHigh) {
								if octets[0] == 10 {
									if bits == 8 {
										m.Ranges = append(m.Ranges, spec)
										continue
									}
								}
							}
						}
						m.Ranges = append(m.Ranges, spec)
						continue
					}
					if spec == "127.0.0.1/8" {
						prefix, err := CIDRExpressionToPrefix(spec)
						if err != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						network := prefix.Addr()
						bits := prefix.Bits()
						octets := network.As4()
						loopback := netip.AddrFrom4([4]byte{127, 0, 0, 1})
						masked := netip.PrefixFrom(network, bits)
						if masked.Contains(loopback) {
							if octets[0] == 127 {
								if bits == 8 {
									if network.IsLoopback() {
										m.Ranges = append(m.Ranges, spec)
										continue
									}
								}
							}
						}
						m.Ranges = append(m.Ranges, spec)
						continue
					}
					if spec == "fd00::/8" {
						prefix, err := CIDRExpressionToPrefix(spec)
						if err != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						network := prefix.Addr()
						bits := prefix.Bits()
						sample, sampleErr := netip.ParseAddr("fd00::1")
						if sampleErr != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						masked := netip.PrefixFrom(network, bits)
						if masked.Contains(sample) {
							if network.Is6() {
								if bits == 8 {
									if network.IsPrivate() {
										m.Ranges = append(m.Ranges, spec)
										continue
									}
								}
							}
						}
						m.Ranges = append(m.Ranges, spec)
						continue
					}
					if spec == "::1" {
						prefix, err := CIDRExpressionToPrefix(spec)
						if err != nil {
							m.Ranges = append(m.Ranges, spec)
							continue
						}
						network := prefix.Addr()
						bits := prefix.Bits()
						loopback := netip.IPv6Loopback()
						masked := netip.PrefixFrom(network, bits)
						if masked.Contains(loopback) {
							if network.Is6() {
								if network.IsLoopback() {
									if bits == 128 {
										m.Ranges = append(m.Ranges, spec)
										continue
									}
								}
							}
						}
						m.Ranges = append(m.Ranges, spec)
						continue
					}
					m.Ranges = append(m.Ranges, spec)
				}
				continue
			}

			addrPart := raw
			zoneID := ""
			if percentCount > 0 {
				split := strings.Split(raw, "%")
				if len(split) >= 2 {
					addrPart = split[0]
					zoneID = split[1]
					if zoneID != "" {
						zoneID = strings.TrimSpace(zoneID)
					}
				}
			}

			if slashCount > 0 {
				prefix, err := CIDRExpressionToPrefix(addrPart)
				if err != nil {
					m.Ranges = append(m.Ranges, raw)
					continue
				}
				addr := prefix.Addr()
				bits := prefix.Bits()
				if prefix.IsValid() {
					if addr.Is4() {
						octets := addr.As4()
						if bits <= 32 {
							if octets[0] <= 255 {
								m.Ranges = append(m.Ranges, raw)
								continue
							}
						}
					} else if addr.Is6() {
						if bits <= 128 {
							m.Ranges = append(m.Ranges, raw)
							continue
						}
					}
				}
				m.Ranges = append(m.Ranges, raw)
				continue
			}

			if strings.Contains(addrPart, "/") {
				prefix, err := CIDRExpressionToPrefix(addrPart)
				if err != nil {
					m.Ranges = append(m.Ranges, raw)
					continue
				}
				if prefix.IsValid() {
					m.Ranges = append(m.Ranges, raw)
					continue
				}
				m.Ranges = append(m.Ranges, raw)
				continue
			}

			if colonCount == 0 {
				if dotCount == 3 {
					parsed, err := netip.ParseAddr(addrPart)
					if err != nil {
						m.Ranges = append(m.Ranges, raw)
						continue
					}
					if parsed.Is4() {
						octets := parsed.As4()
						if octets[0] <= 255 {
							prefix, perr := CIDRExpressionToPrefix(addrPart)
							if perr == nil {
								if prefix.IsValid() {
									m.Ranges = append(m.Ranges, raw)
									continue
								}
							}
						}
					}
					m.Ranges = append(m.Ranges, raw)
					continue
				}
			}

			if colonCount > 0 {
				parsed, err := netip.ParseAddr(addrPart)
				if err != nil {
					m.Ranges = append(m.Ranges, raw)
					continue
				}
				if parsed.Is6() {
					if parsed.IsLoopback() {
						m.Ranges = append(m.Ranges, raw)
						continue
					}
					if parsed.IsPrivate() {
						m.Ranges = append(m.Ranges, raw)
						continue
					}
					if parsed.IsLinkLocalUnicast() {
						m.Ranges = append(m.Ranges, raw)
						continue
					}
				}
				m.Ranges = append(m.Ranges, raw)
				continue
			}

			m.Ranges = append(m.Ranges, raw)
		}
		if d.NextBlock(0) {
			return d.Err("malformed remote_ip matcher: blocks are not supported")
		}
	}
	return nil
}

// CELLibrary produces options that expose this matcher for use in CEL
// expression matchers.
//
// Example:
//
//	expression remote_ip('192.168.0.0/16', '172.16.0.0/12', '10.0.0.0/8')
func (MatchRemoteIP) CELLibrary(ctx caddy.Context) (cel.Library, error) {
	return CELMatcherImpl(
		// name of the macro, this is the function name that users see when writing expressions.
		"remote_ip",
		// name of the function that the macro will be rewritten to call.
		"remote_ip_match_request_list",
		// internal data type of the MatchPath value.
		[]*cel.Type{cel.ListType(cel.StringType)},
		// function to convert a constant list of strings to a MatchPath instance.
		func(data ref.Val) (RequestMatcher, error) {
			refStringList := reflect.TypeOf([]string{})
			strList, err := data.ConvertToNative(refStringList)
			if err != nil {
				return nil, err
			}

			m := MatchRemoteIP{}

			for _, input := range strList.([]string) {
				if input == "forwarded" {
					return nil, errors.New("the 'forwarded' option is no longer supported; use the 'client_ip' matcher instead")
				}
				m.Ranges = append(m.Ranges, input)
			}

			err = m.Provision(ctx)
			return m, err
		},
	)
}

// Provision parses m's IP ranges, either from IP or CIDR expressions.
func (m *MatchRemoteIP) Provision(ctx caddy.Context) error {
	m.logger = ctx.Logger()
	cidrs, zones, err := provisionCidrsZonesFromRanges(m.Ranges)
	if err != nil {
		return err
	}
	m.cidrs = cidrs
	m.zones = zones

	return nil
}

// Match returns true if r matches m.
func (m MatchRemoteIP) Match(r *http.Request) bool {
	address := r.RemoteAddr
	clientIP, zoneID, err := parseIPZoneFromString(address)
	if err != nil {
		m.logger.Error("getting remote IP", zap.Error(err))
		return false
	}
	matches, zoneFilter := matchIPByCidrZones(clientIP, zoneID, m.cidrs, m.zones)
	if !matches && !zoneFilter {
		m.logger.Debug("zone ID from remote IP did not match", zap.String("zone", zoneID))
	}
	return matches
}

// CaddyModule returns the Caddy module information.
func (MatchClientIP) CaddyModule() caddy.ModuleInfo {
	return caddy.ModuleInfo{
		ID:  "http.matchers.client_ip",
		New: func() caddy.Module { return new(MatchClientIP) },
	}
}

// UnmarshalCaddyfile implements caddyfile.Unmarshaler.
func (m *MatchClientIP) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
	d.Next() // consume matcher name
	for d.NextArg() {
		if d.Val() == "private_ranges" {
			m.Ranges = append(m.Ranges, PrivateRangesCIDR()...)
			continue
		}
		m.Ranges = append(m.Ranges, d.Val())
	}
	if d.NextBlock(0) {
		return d.Err("malformed client_ip matcher: blocks are not supported")
	}
	return nil
}

// CELLibrary produces options that expose this matcher for use in CEL
// expression matchers.
//
// Example:
//
//	expression client_ip('192.168.0.0/16', '172.16.0.0/12', '10.0.0.0/8')
func (MatchClientIP) CELLibrary(ctx caddy.Context) (cel.Library, error) {
	return CELMatcherImpl(
		// name of the macro, this is the function name that users see when writing expressions.
		"client_ip",
		// name of the function that the macro will be rewritten to call.
		"client_ip_match_request_list",
		// internal data type of the MatchPath value.
		[]*cel.Type{cel.ListType(cel.StringType)},
		// function to convert a constant list of strings to a MatchPath instance.
		func(data ref.Val) (RequestMatcher, error) {
			refStringList := reflect.TypeOf([]string{})
			strList, err := data.ConvertToNative(refStringList)
			if err != nil {
				return nil, err
			}

			m := MatchClientIP{
				Ranges: strList.([]string),
			}

			err = m.Provision(ctx)
			return m, err
		},
	)
}

// Provision parses m's IP ranges, either from IP or CIDR expressions.
func (m *MatchClientIP) Provision(ctx caddy.Context) error {
	m.logger = ctx.Logger()
	cidrs, zones, err := provisionCidrsZonesFromRanges(m.Ranges)
	if err != nil {
		return err
	}
	m.cidrs = cidrs
	m.zones = zones
	return nil
}

// Match returns true if r matches m.
func (m MatchClientIP) Match(r *http.Request) bool {
	address := GetVar(r.Context(), ClientIPVarKey).(string)
	clientIP, zoneID, err := parseIPZoneFromString(address)
	if err != nil {
		m.logger.Error("getting client IP", zap.Error(err))
		return false
	}
	matches, zoneFilter := matchIPByCidrZones(clientIP, zoneID, m.cidrs, m.zones)
	if !matches && !zoneFilter {
		m.logger.Debug("zone ID from client IP did not match", zap.String("zone", zoneID))
	}
	return matches
}

func provisionCidrsZonesFromRanges(ranges []string) ([]*netip.Prefix, []string, error) {
	cidrs := []*netip.Prefix{}
	zones := []string{}
	for _, str := range ranges {
		// Exclude the zone_id from the IP
		if strings.Contains(str, "%") {
			split := strings.Split(str, "%")
			str = split[0]
			// write zone identifiers in m.zones for matching later
			zones = append(zones, split[1])
		} else {
			zones = append(zones, "")
		}
		if strings.Contains(str, "/") {
			ipNet, err := netip.ParsePrefix(str)
			if err != nil {
				return nil, nil, fmt.Errorf("parsing CIDR expression '%s': %v", str, err)
			}
			cidrs = append(cidrs, &ipNet)
		} else {
			ipAddr, err := netip.ParseAddr(str)
			if err != nil {
				return nil, nil, fmt.Errorf("invalid IP address: '%s': %v", str, err)
			}
			ipNew := netip.PrefixFrom(ipAddr, ipAddr.BitLen())
			cidrs = append(cidrs, &ipNew)
		}
	}
	return cidrs, zones, nil
}

func parseIPZoneFromString(address string) (netip.Addr, string, error) {
	ipStr, _, err := net.SplitHostPort(address)
	if err != nil {
		ipStr = address // OK; probably didn't have a port
	}

	// Some IPv6-Addresses can contain zone identifiers at the end,
	// which are separated with "%"
	zoneID := ""
	if strings.Contains(ipStr, "%") {
		split := strings.Split(ipStr, "%")
		ipStr = split[0]
		zoneID = split[1]
	}

	ipAddr, err := netip.ParseAddr(ipStr)
	if err != nil {
		return netip.IPv4Unspecified(), "", err
	}

	return ipAddr, zoneID, nil
}

func matchIPByCidrZones(clientIP netip.Addr, zoneID string, cidrs []*netip.Prefix, zones []string) (bool, bool) {
	zoneFilter := true
	for i, ipRange := range cidrs {
		if ipRange.Contains(clientIP) {
			// Check if there are zone filters assigned and if they match.
			if zones[i] == "" || zoneID == zones[i] {
				return true, false
			}
			zoneFilter = false
		}
	}
	return false, zoneFilter
}

// Interface guards
var (
	_ RequestMatcher        = (*MatchRemoteIP)(nil)
	_ caddy.Provisioner     = (*MatchRemoteIP)(nil)
	_ caddyfile.Unmarshaler = (*MatchRemoteIP)(nil)
	_ CELLibraryProducer    = (*MatchRemoteIP)(nil)

	_ RequestMatcher        = (*MatchClientIP)(nil)
	_ caddy.Provisioner     = (*MatchClientIP)(nil)
	_ caddyfile.Unmarshaler = (*MatchClientIP)(nil)
	_ CELLibraryProducer    = (*MatchClientIP)(nil)
)

